def full_read_only_launch_pin_audit(project_root, pins):
    # Specification candidate: returns all mismatches, never spawns a process.
    specs = []
    for name, pin in pins["tools"].items():
        specs.append(("tool:" + name, Path(pin["path"]), pin["sha256"], pin["size"]))
    for name in ("binary", "viteCli"):
        pin = pins[name]
        specs.append((name, project_root / pin["path"], pin["sha256"], pin["size"]))
    for rel, expected in pins["sourceSha256"].items():
        specs.append(("source:" + rel, project_root / rel, expected, None))
    rows = []
    for name, path, expected_sha, expected_size in specs:
        row = {"name": name, "path": str(path), "matches": False}
        try:
            if not path.is_absolute() or path.is_symlink() or not path.is_file():
                raise ValueError("STATIC_PIN_PATH_INVALID")
            if type(expected_sha) is not str or re.fullmatch(r"[0-9a-f]{64}", expected_sha) is None:
                raise ValueError("STATIC_PIN_DIGEST_INVALID")
            if expected_size is not None and (type(expected_size) is not int or expected_size < 1):
                raise ValueError("STATIC_PIN_SIZE_INVALID")
            raw = path.read_bytes()
            actual_sha = hashlib.sha256(raw).hexdigest()
            row.update(actualSha256=actual_sha, actualSize=len(raw),
                       matches=actual_sha == expected_sha and
                       (expected_size is None or len(raw) == expected_size))
        except (OSError, ValueError) as error:
            row["error"] = type(error).__name__
        rows.append(row)
    return {"status": "PASS" if len(rows) == 20 and all(r["matches"] for r in rows) else "HOLD",
            "rows": rows, "controllerInvoked": False, "osIdentityQuery": False}
